// Safeguard marker: INSTAOPS_V2_PUBLISH — Meta Graph API v22.0 for Reels, Images, and 2-10 Mixed Carousels.
function readCfg(key, fallback) {
  var blocked = false;
  try {
    if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') {
      return { value: String($env[key]), source: 'env', blocked: false };
    }
  } catch (_) { blocked = true; }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') {
      return { value: String($vars[key]), source: 'vars', blocked: blocked };
    }
  } catch (_) {}
  return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
}

function safeEqual(a, b) {
  if (!a || a.length !== b.length) return false;
  var diff = 0;
  for (var i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

var item = $input.first().json || {};
var headers = item.headers || {};
var body = item.body || item;
var secretCfg = readCfg('N8N_WEBHOOK_SECRET', '');
var livePubCfg = readCfg('LIVE_PUBLISH_ENABLED', 'false');
var expected = secretCfg.value;
var provided = String(headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '');

var postUuid = String(body.post_uuid || '').trim();
var postId = String(body.post_id || '').trim();
var reviewedRevision = String(body.reviewed_revision || '').trim();
var approvedRevision = String(body.approved_revision || '').trim();
var uuidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(postUuid);
var livePubEnabled = livePubCfg.value.toLowerCase() === 'true';

var error = '';
var httpStatus = 202;
if (secretCfg.blocked && !expected) {
  error = 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.';
  httpStatus = 500;
} else if (!expected || !safeEqual(provided, expected)) {
  error = 'Unauthorized webhook secret.';
  httpStatus = 403;
} else if (livePubCfg.blocked && livePubCfg.source === 'missing') {
  error = 'n8n $env access denied for LIVE_PUBLISH_ENABLED flag.';
  httpStatus = 500;
} else if (!livePubEnabled) {
  error = 'Live publishing blocked inside W02: LIVE_PUBLISH_ENABLED is not true.';
  httpStatus = 409;
} else if (body.confirm !== true || !uuidOk || !postId || !reviewedRevision) {
  error = 'Explicit confirm: true, valid post_uuid, post_id, and reviewed_revision are required.';
  httpStatus = 422;
} else if (approvedRevision && approvedRevision !== reviewedRevision) {
  error = 'Approval revision mismatch in publish request.';
  httpStatus = 409;
}

return [{
  json: {
    valid: !error,
    error: error,
    httpStatus: httpStatus,
    post_uuid: postUuid,
    post_id: postId,
    ig_user_id: String(body.ig_user_id || readCfg('INSTAGRAM_USER_ID', '17841453414532595').value).trim(),
    reviewed_revision: reviewedRevision,
    approved_revision: approvedRevision || reviewedRevision,
    request_id: String(body.request_id || ''),
    job_id: String(body.job_id || ''),
    lock_key: String(body.lock_key || ('post:' + postUuid)),
    lock_owner: String(body.lock_owner || ''),
    execution_id: String((typeof $execution !== 'undefined' && $execution && $execution.id) || ''),
    started_at: new Date().toISOString(),
    _untrusted_request_media_ignored: true
  }
}];

// Safeguard marker: INSTAOPS_V2_PUBLISH — Supabase authoritative assets, strict revision OR-check, bounded child & parent container polling, single media_publish + immediate published_id persistence.
return (async function () {
  var self = this;
  function readCfg(key, fallback) {
    var blocked = false;
    try {
      if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') {
        return { value: String($env[key]), source: 'env', blocked: false };
      }
    } catch (_) { blocked = true; }
    try {
      if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') {
        return { value: String($vars[key]), source: 'vars', blocked: blocked };
      }
    } catch (_) {}
    return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
  }

  async function httpCall(opts) {
    if (self && self.helpers && typeof self.helpers.httpRequest === 'function') {
      return await self.helpers.httpRequest(opts);
    }
    if (typeof fetch === 'function') {
      var headers = Object.assign({}, opts.headers || {});
      var body;
      if (opts.body !== undefined) {
        if (typeof opts.body === 'string') {
          body = opts.body;
        } else {
          headers['Content-Type'] = headers['Content-Type'] || 'application/json';
          body = JSON.stringify(opts.body);
        }
      }
      var res = await fetch(opts.url, { method: opts.method || 'GET', headers: headers, body: body });
      var text = await res.text();
      var parsed = text;
      try { parsed = text ? JSON.parse(text) : {}; } catch (_) {}
      return { statusCode: res.status, body: parsed, headers: {} };
    }
    throw new Error('No HTTP request helper available.');
  }

  async function sleepMs(ms) {
    if (ms > 0 && typeof setTimeout === 'function') {
      await new Promise(function (resolve) { setTimeout(resolve, ms); });
    }
  }

  function safeSlug(v) {
    return String(v || '').replace(/[^A-Za-z0-9_-]+/g, '_').slice(0, 40);
  }

  function isSafeHttpsUrl(raw) {
    try {
      var u = new URL(String(raw || '').trim());
      return u.protocol === 'https:' && !/^(127\.|10\.|192\.168\.|169\.254\.)/.test(u.hostname);
    } catch (_) { return false; }
  }

  var req = $('CODE | Verify Auth & Approval Gate').item.json;
  var sbUrlCfg = readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co');
  var sbKeyCfg = readCfg('SUPABASE_SERVICE_ROLE_KEY', '');
  var metaTokenCfg = readCfg('META_GRAPH_TOKEN', '');
  var graphVerCfg = readCfg('INSTAGRAM_GRAPH_VERSION', 'v22.0');
  var livePubCfg = readCfg('LIVE_PUBLISH_ENABLED', 'false');
  var pollWaitMs = Math.max(0, Math.min(15000, Number(readCfg('N8N_GRAPH_POLL_INTERVAL_MS', '3000').value) || 3000));
  var maxPolls = Math.max(1, Math.min(30, Number(readCfg('N8N_GRAPH_MAX_POLLS', '15').value) || 15));

  if (livePubCfg.value.toLowerCase() !== 'true') {
    return [{ json: { ok: false, status: 'REJECTED', error: 'LIVE_PUBLISH_ENABLED is false inside W02.' } }];
  }
  if (!sbKeyCfg.value || !metaTokenCfg.value) {
    return [{ json: { ok: false, status: 'FAILED', error: (sbKeyCfg.blocked || metaTokenCfg.blocked) ? 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.' : 'Missing SUPABASE_SERVICE_ROLE_KEY or META_GRAPH_TOKEN.' } }];
  }

  var sbUrl = sbUrlCfg.value.replace(/\/$/, '');
  var sbKey = sbKeyCfg.value;
  var metaToken = metaTokenCfg.value;
  var graphVer = graphVerCfg.value || 'v22.0';
  var sbHeaders = { apikey: sbKey, Authorization: 'Bearer ' + sbKey, 'Content-Type': 'application/json' };
  var graphHeaders = { Authorization: 'Bearer ' + metaToken, 'Content-Type': 'application/json' };
  var execStart = Date.now();

  async function sbRpc(fnName, params) {
    return await httpCall({ method: 'POST', url: sbUrl + '/rest/v1/rpc/' + fnName, headers: sbHeaders, body: params, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  }
  async function sbRest(method, path, body) {
    return await httpCall({ method: method, url: sbUrl + '/rest/v1/' + path, headers: sbHeaders, body: body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  }
  async function graphCall(method, path, body) {
    return await httpCall({
      method: method,
      url: 'https://graph.facebook.com/' + graphVer + '/' + path,
      headers: graphHeaders,
      body: body,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 30000
    });
  }

  var workerOwner = 'w02:' + (req.execution_id || req.request_id || Date.now());
  var lockRes = await sbRpc('instaops_transfer_or_claim_lock', {
    p_lock_key: req.lock_key,
    p_post_uuid: req.post_uuid,
    p_post_id: req.post_id,
    p_operation: 'PUBLISH',
    p_expected_owner: req.lock_owner || '',
    p_new_owner: workerOwner,
    p_request_id: req.request_id,
    p_lease_seconds: 600
  });
  var lockRows = Array.isArray(lockRes.body) ? lockRes.body : [lockRes.body];
  var lockRow = lockRows[0] || {};
  if (lockRes.statusCode >= 300 || lockRow.acquired !== true) {
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), {
        status: 'FAILED', stage: 'LOCK_CONFLICT', execution_id: req.execution_id,
        error_code: 'POST_LOCKED', error_message: String(lockRow.reason || 'Publish lock conflict'), finished_at: new Date().toISOString()
      });
    }
    return [{ json: { ok: false, status: 'LOCK_CONFLICT', error: String(lockRow.reason || 'Publish lock held by another worker') } }];
  }

  var currentRev = 0;
  async function enqueueSync(entityType, entityUuid, extId, op, payload, srcRev) {
    await sbRest('POST', 'instaops_sync_queue', {
      entity_type: entityType,
      entity_uuid: entityUuid,
      external_id: extId,
      operation: op,
      payload: payload,
      source_revision: srcRev || 0,
      idempotency_key: entityType.toLowerCase() + ':' + entityUuid + ':' + Date.now() + ':' + Math.floor(Math.random() * 10000),
      status: 'PENDING'
    });
  }

  async function markUncertain(stage, msg, extraPostPatch) {
    // CRITICAL: Preserve lock on uncertain publish outcome so manual reconciliation is enforced!
    var nowIso = new Date().toISOString();
    var patch = Object.assign({
      status: 'VERIFY_MANUALLY',
      error: String(msg || 'Publish outcome uncertain; verify manually on Instagram').slice(0, 500),
      error_code: 'PUBLISH_OUTCOME_UNKNOWN',
      error_stage: stage || 'PUBLISHING_MEDIA',
      sheets_sync_status: 'PENDING'
    }, extraPostPatch || {});
    var pRes = await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), patch);
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), {
        status: 'OUTCOME_UNKNOWN', stage: 'OUTCOME_UNKNOWN', execution_id: req.execution_id,
        error_code: 'PUBLISH_OUTCOME_UNKNOWN', error_message: String(msg || '')
      });
    }
    var savedRow = Array.isArray(pRes.body) && pRes.body[0] ? pRes.body[0] : Object.assign({ id: req.post_uuid, post_id: req.post_id }, patch);
    await enqueueSync('POST', req.post_uuid, req.post_id, 'UPSERT', { post_uuid: req.post_uuid, row: savedRow }, currentRev);
    await sbRest('POST', 'instaops_execution_logs', {
      log_id: 'log_' + Date.now() + '_' + safeSlug(req.post_id), request_id: req.request_id, execution_id: req.execution_id,
      workflow_id: 'w02-publish', workflow_name: 'W02 Publish Content', post_id: req.post_id, operation: 'PUBLISH', trigger_source: 'DASHBOARD',
      stage: stage || 'OUTCOME_UNKNOWN', status: 'OUTCOME_UNKNOWN', started_at: req.started_at, finished_at: nowIso, duration_ms: Date.now() - execStart,
      error_code: 'PUBLISH_OUTCOME_UNKNOWN', error_message: String(msg || ''), retryable: false
    });
    return [{ json: { ok: false, post_uuid: req.post_uuid, post_id: req.post_id, status: 'VERIFY_MANUALLY', error_code: 'PUBLISH_OUTCOME_UNKNOWN', error: msg, lock_preserved: true } }];
  }

  async function failConfirmedPrePublish(errCode, errStage, errMsg, shouldUpdatePost) {
    var nowIso = new Date().toISOString();
    if (shouldUpdatePost) {
      var pRes = await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), {
        status: 'FAILED', error: String(errMsg || '').slice(0, 500), error_code: errCode, error_stage: errStage, sheets_sync_status: 'PENDING'
      });
      var savedRow = Array.isArray(pRes.body) && pRes.body[0] ? pRes.body[0] : { id: req.post_uuid, post_id: req.post_id, status: 'FAILED', error_code: errCode, error: errMsg };
      await enqueueSync('POST', req.post_uuid, req.post_id, 'UPSERT', { post_uuid: req.post_uuid, row: savedRow }, currentRev);
    }
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), {
        status: 'FAILED', stage: errStage || 'FAILED', execution_id: req.execution_id,
        error_code: errCode, error_message: String(errMsg || ''), finished_at: nowIso
      });
    }
    await sbRest('POST', 'instaops_execution_logs', {
      log_id: 'log_' + Date.now() + '_' + safeSlug(req.post_id), request_id: req.request_id, execution_id: req.execution_id,
      workflow_id: 'w02-publish', workflow_name: 'W02 Publish Content', post_id: req.post_id, operation: 'PUBLISH', trigger_source: 'DASHBOARD',
      stage: errStage || 'FAILED', status: 'FAILED', started_at: req.started_at, finished_at: nowIso, duration_ms: Date.now() - execStart,
      error_code: errCode, error_message: String(errMsg || ''), retryable: true
    });
    await sbRpc('instaops_release_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner });
    return [{ json: { ok: false, post_uuid: req.post_uuid, post_id: req.post_id, status: 'FAILED', error_code: errCode, error: errMsg } }];
  }

  async function pollContainerUntilReady(containerId, label) {
    for (var attempt = 1; attempt <= maxPolls; attempt++) {
      if (attempt > 1) await sleepMs(pollWaitMs);
      if (attempt % 2 === 0) {
        await sbRpc('instaops_renew_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner, p_lease_seconds: 600 });
      }
      var stRes;
      try {
        stRes = await graphCall('GET', encodeURIComponent(containerId) + '?fields=id,status_code,status');
      } catch (pollNetErr) {
        return { ok: false, uncertain: true, error: label + ' polling timeout/network error: ' + (pollNetErr && pollNetErr.message ? pollNetErr.message : 'network error') };
      }
      var stBody = stRes.body || {};
      if (stRes.statusCode >= 500) {
        if (attempt < maxPolls) continue;
        return { ok: false, uncertain: true, error: label + ' Graph HTTP ' + stRes.statusCode };
      }
      if (stRes.statusCode >= 400 || stBody.error) {
        return { ok: false, uncertain: false, code: 'META_CONTAINER_ERROR', error: (stBody.error && stBody.error.message) || (label + ' Graph status error HTTP ' + stRes.statusCode) };
      }
      var code = String(stBody.status_code || stBody.status || '').toUpperCase();
      if (code === 'FINISHED' || code === 'PUBLISHED') {
        return { ok: true, status_code: code, id: containerId };
      }
      if (code === 'ERROR' || code === 'EXPIRED') {
        return { ok: false, uncertain: false, code: code === 'EXPIRED' ? 'META_CONTAINER_EXPIRED' : 'META_CONTAINER_ERROR', error: label + ' container status_code=' + code };
      }
    }
    return { ok: false, uncertain: true, error: label + ' container ' + containerId + ' exceeded bounded polling limit (' + maxPolls + ' checks).' };
  }

  try {
    // 1. Load authoritative post, active media_assets, and account status from Supabase (never trust request media URLs!)
    var postGet = await sbRest('GET', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid) + '&select=*');
    var post = Array.isArray(postGet.body) ? postGet.body[0] : null;
    if (!post) {
      return await failConfirmedPrePublish('POST_NOT_FOUND', 'VALIDATING', 'Post UUID ' + req.post_uuid + ' not found in Supabase.', false);
    }
    currentRev = Number(post.revision || 0);
    var reqRev = Number(req.reviewed_revision || 0);
    var approvedRev = Number(post.approved_revision || 0);

    if (post.deleted_at || post.status === 'DELETED' || post.status === 'ARCHIVED') {
      return await failConfirmedPrePublish('POST_DELETED_OR_ARCHIVED', 'VALIDATING', 'Cannot publish deleted or archived post.', false);
    }
    if (post.status === 'PUBLISHED' || (post.published_id && String(post.published_id).trim() !== '')) {
      return await failConfirmedPrePublish('ALREADY_PUBLISHED', 'VALIDATING', 'Post is already published (' + post.published_id + ').', false);
    }
    if (post.status !== 'READY' && post.status !== 'SCHEDULED') {
      return await failConfirmedPrePublish('POST_LOCKED', 'VALIDATING', 'Post status ' + post.status + ' is not eligible for publishing.', false);
    }
    if (!currentRev || !reqRev || !approvedRev || reqRev !== currentRev || approvedRev !== currentRev) {
      return await failConfirmedPrePublish('REVISION_CONFLICT', 'VALIDATING', 'Revision mismatch (db=' + currentRev + ', approved=' + approvedRev + ', reviewed=' + reqRev + ').', false);
    }

    var igUserId = String(post.ig_user_id || req.ig_user_id || '').trim();
    var acctRes = await sbRest('GET', 'instaops_accounts?ig_user_id=eq.' + encodeURIComponent(igUserId) + '&limit=1');
    var acct = Array.isArray(acctRes.body) ? acctRes.body[0] : null;
    if (!acct || acct.enabled !== true) {
      return await failConfirmedPrePublish('ACCOUNT_DISABLED', 'VALIDATING', 'Destination account ' + igUserId + ' is disabled or missing in instaops_accounts.', false);
    }

    var assetsRes = await sbRest('GET', 'instaops_media_assets?post_uuid=eq.' + encodeURIComponent(req.post_uuid) + '&storage_status=eq.ACTIVE&order=media_index.asc');
    var assets = (Array.isArray(assetsRes.body) ? assetsRes.body : []).sort(function (a, b) { return Number(a.media_index || 0) - Number(b.media_index || 0); });
    var caption = String(post.caption || post.original_caption || '');
    if (caption.length > 2200) {
      return await failConfirmedPrePublish('CAPTION_TOO_LONG', 'VALIDATING', 'Caption exceeds Meta Graph 2,200 character limit.', false);
    }
    var mediaType = String(post.media_type || (assets.length > 1 ? 'CAROUSEL' : 'REEL')).toUpperCase();
    if (mediaType === 'CAROUSEL') {
      if (assets.length < 2 || assets.length > 10) {
        return await failConfirmedPrePublish('INVALID_CAROUSEL_COUNT', 'VALIDATING', 'Carousel requires 2-10 ACTIVE assets (found ' + assets.length + ').', false);
      }
    } else if (assets.length !== 1) {
      return await failConfirmedPrePublish('MISSING_MEDIA_ASSET', 'VALIDATING', mediaType + ' requires exactly 1 ACTIVE DB asset (found ' + assets.length + ').', false);
    }

    for (var ai = 0; ai < assets.length; ai++) {
      if (!isSafeHttpsUrl(assets[ai].secure_url)) {
        return await failConfirmedPrePublish('INVALID_MEDIA_URL', 'VALIDATING', 'DB asset ' + ai + ' has missing or unsafe HTTPS URL.', false);
      }
    }

    // Transition authoritative state to PUBLISHING
    await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), {
      status: 'PUBLISHING', execution_id: req.execution_id, request_id: req.request_id, error: '', error_code: '', error_stage: ''
    });
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), {
        status: 'RUNNING', stage: 'CREATING_CONTAINER', execution_id: req.execution_id, lock_key: req.lock_key, lock_owner: workerOwner
      });
    }

    var parentContainerId = '';
    var childIds = [];

    if (mediaType === 'CAROUSEL') {
      // Create ALL 2..10 children in exact media_index order; abort cleanly if any fails
      for (var cIdx = 0; cIdx < assets.length; cIdx++) {
        var childAsset = assets[cIdx];
        var isChildVid = String(childAsset.resource_type || '').toLowerCase() === 'video' || String(childAsset.media_type || '').toUpperCase() === 'VIDEO';
        var childPayload = isChildVid
          ? { media_type: 'VIDEO', video_url: childAsset.secure_url, is_carousel_item: true }
          : { image_url: childAsset.secure_url, is_carousel_item: true };

        var cRes;
        try {
          cRes = await graphCall('POST', encodeURIComponent(igUserId) + '/media', childPayload);
        } catch (cNetErr) {
          return await failConfirmedPrePublish('CAROUSEL_CHILD_FAILED', 'CREATING_CONTAINER', 'Child ' + cIdx + ' creation failed: ' + (cNetErr && cNetErr.message ? cNetErr.message : 'network error'), true);
        }
        var cBody = cRes.body || {};
        if (cRes.statusCode >= 300 || cBody.error || !cBody.id) {
          var cErr = (cBody.error && cBody.error.message) || ('Child ' + cIdx + ' creation failed (HTTP ' + cRes.statusCode + ')');
          return await failConfirmedPrePublish('CAROUSEL_CHILD_FAILED', 'CREATING_CONTAINER', cErr, true);
        }
        var childId = String(cBody.id);
        childIds.push(childId);
        if (childAsset.id) {
          await sbRest('PATCH', 'instaops_media_assets?id=eq.' + encodeURIComponent(childAsset.id), { ig_child_container_id: childId });
        }
      }
      await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), { child_container_ids: childIds });

      // Bounded poll for ALL video (or pending) child containers until FINISHED before parent creation
      if (req.job_id) {
        await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), { stage: 'POLLING_CHILDREN' });
      }
      for (var pIdx = 0; pIdx < assets.length; pIdx++) {
        var pChildAsset = assets[pIdx];
        var isVidChild = String(pChildAsset.resource_type || '').toLowerCase() === 'video' || String(pChildAsset.media_type || '').toUpperCase() === 'VIDEO';
        if (isVidChild) {
          var childPoll = await pollContainerUntilReady(childIds[pIdx], 'CAROUSEL_CHILD_' + pIdx);
          if (!childPoll.ok) {
            if (childPoll.uncertain) return await markUncertain('POLLING_CHILDREN', childPoll.error, { child_container_ids: childIds });
            return await failConfirmedPrePublish(childPoll.code || 'CAROUSEL_CHILD_ERROR', 'POLLING_CHILDREN', childPoll.error, true);
          }
        }
      }

      // All children ready -> create parent CAROUSEL container
      var pContRes;
      try {
        pContRes = await graphCall('POST', encodeURIComponent(igUserId) + '/media', {
          media_type: 'CAROUSEL',
          children: childIds.join(','),
          caption: caption
        });
      } catch (parErr) {
        return await failConfirmedPrePublish('CAROUSEL_PARENT_FAILED', 'CREATING_CONTAINER', 'Parent container creation failed: ' + (parErr && parErr.message ? parErr.message : 'network error'), true);
      }
      var pContBody = pContRes.body || {};
      if (pContRes.statusCode >= 300 || pContBody.error || !pContBody.id) {
        return await failConfirmedPrePublish('CAROUSEL_PARENT_FAILED', 'CREATING_CONTAINER', (pContBody.error && pContBody.error.message) || ('Parent container error HTTP ' + pContRes.statusCode), true);
      }
      parentContainerId = String(pContBody.id);
    } else {
      // Single REEL or IMAGE
      var singleAsset = assets[0];
      var singlePayload = (mediaType === 'IMAGE' && String(singleAsset.resource_type || '') !== 'video')
        ? { image_url: singleAsset.secure_url, caption: caption }
        : { media_type: 'REELS', video_url: singleAsset.secure_url, caption: caption };
      var sContRes;
      try {
        sContRes = await graphCall('POST', encodeURIComponent(igUserId) + '/media', singlePayload);
      } catch (sErr) {
        return await failConfirmedPrePublish('CONTAINER_CREATE_FAILED', 'CREATING_CONTAINER', sErr && sErr.message ? sErr.message : 'Container creation failed', true);
      }
      var sContBody = sContRes.body || {};
      if (sContRes.statusCode >= 300 || sContBody.error || !sContBody.id) {
        return await failConfirmedPrePublish('CONTAINER_CREATE_FAILED', 'CREATING_CONTAINER', (sContBody.error && sContBody.error.message) || ('Container creation failed HTTP ' + sContRes.statusCode), true);
      }
      parentContainerId = String(sContBody.id);
    }

    await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), { container_id: parentContainerId, child_container_ids: childIds });
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), { stage: 'POLLING_CONTAINER' });
    }

    var parentPoll = await pollContainerUntilReady(parentContainerId, mediaType + '_PARENT');
    if (!parentPoll.ok) {
      if (parentPoll.uncertain) return await markUncertain('POLLING_CONTAINER', parentPoll.error, { container_id: parentContainerId });
      return await failConfirmedPrePublish(parentPoll.code || 'CONTAINER_FAILED', 'POLLING_CONTAINER', parentPoll.error, true);
    }

    // Guard against double-publishing an already PUBLISHED container
    if (parentPoll.status_code === 'PUBLISHED') {
      return await markUncertain('ALREADY_PUBLISHED_CONTAINER', 'Container ' + parentContainerId + ' already reports status_code=PUBLISHED; skipped duplicate media_publish.', { container_id: parentContainerId });
    }

    await sbRpc('instaops_renew_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner, p_lease_seconds: 600 });
    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), { stage: 'PUBLISHING_MEDIA' });
    }

    var pubRes;
    try {
      pubRes = await graphCall('POST', encodeURIComponent(igUserId) + '/media_publish', { creation_id: parentContainerId });
    } catch (pubNetErr) {
      return await markUncertain('PUBLISHING_MEDIA', 'media_publish network/timeout error: ' + (pubNetErr && pubNetErr.message ? pubNetErr.message : 'timeout'), { container_id: parentContainerId });
    }
    var pubBody = pubRes.body || {};
    if (pubRes.statusCode >= 500) {
      return await markUncertain('PUBLISHING_MEDIA', 'media_publish ambiguous HTTP ' + pubRes.statusCode, { container_id: parentContainerId });
    }
    if (pubRes.statusCode >= 400 || pubBody.error || !pubBody.id) {
      return await failConfirmedPrePublish('META_PUBLISH_FAILED', 'PUBLISHING_MEDIA', (pubBody.error && pubBody.error.message) || ('media_publish rejected HTTP ' + pubRes.statusCode), true);
    }

    var publishedId = String(pubBody.id);
    var nowIso = new Date().toISOString();

    // CRITICAL: Persist published_id + PUBLISHED status IMMEDIATELY BEFORE fetching permalink so permalink failure never loses published_id or triggers duplicate media_publish!
    var pubSave = await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), {
      status: 'PUBLISHED',
      published_id: publishedId,
      published_at: nowIso,
      processed_at: nowIso,
      container_id: parentContainerId,
      child_container_ids: childIds,
      error: '',
      error_code: '',
      error_stage: '',
      sheets_sync_status: 'PENDING'
    });
    var savedPostRow = Array.isArray(pubSave.body) && pubSave.body[0] ? pubSave.body[0] : Object.assign({}, post, { status: 'PUBLISHED', published_id: publishedId, published_at: nowIso, container_id: parentContainerId });

    // Best-effort permalink lookup (isolated try/catch — never reverts PUBLISHED or retries media_publish)
    var permalink = '';
    try {
      var permRes = await graphCall('GET', encodeURIComponent(publishedId) + '?fields=id,permalink');
      if (permRes.statusCode < 300 && permRes.body && permRes.body.permalink) {
        permalink = String(permRes.body.permalink);
        var permPatch = await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), { published_url: permalink });
        if (Array.isArray(permPatch.body) && permPatch.body[0]) savedPostRow = permPatch.body[0];
        else savedPostRow.published_url = permalink;
      }
    } catch (_) {
      await sbRest('POST', 'instaops_audit_events', {
        post_uuid: req.post_uuid, entity_type: 'POST', entity_id: req.post_id,
        action: 'PERMALINK_FETCH_SKIPPED', details: { published_id: publishedId }
      });
    }

    await enqueueSync('POST', req.post_uuid, req.post_id, 'UPSERT', { post_uuid: req.post_uuid, row: savedPostRow }, currentRev);
    await sbRest('POST', 'instaops_execution_logs', {
      log_id: 'log_' + Date.now() + '_' + safeSlug(req.post_id), request_id: req.request_id, execution_id: req.execution_id,
      workflow_id: 'w02-publish', workflow_name: 'W02 Publish Content', post_id: req.post_id, operation: 'PUBLISH', trigger_source: 'DASHBOARD',
      stage: 'COMPLETED', status: 'SUCCESS', started_at: req.started_at, finished_at: nowIso, duration_ms: Date.now() - execStart, retryable: false
    });
    await enqueueSync('EXECUTION_LOG', req.post_uuid, 'log_' + safeSlug(req.post_id) + '_' + Date.now(), 'UPSERT', {
      log_id: 'log_' + Date.now() + '_' + safeSlug(req.post_id), request_id: req.request_id, execution_id: req.execution_id,
      workflow_id: 'w02-publish', workflow_name: 'W02 Publish Content', post_id: req.post_id, operation: 'PUBLISH', trigger_source: 'DASHBOARD',
      stage: 'COMPLETED', status: 'SUCCESS', started_at: req.started_at, finished_at: nowIso, duration_ms: Date.now() - execStart, retryable: false, created_at: nowIso
    }, currentRev);

    if (req.job_id) {
      await sbRest('PATCH', 'instaops_jobs?job_id=eq.' + encodeURIComponent(req.job_id), {
        status: 'COMPLETED', stage: 'COMPLETED', finished_at: nowIso
      });
    }
    await sbRpc('instaops_release_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner });

    return [{
      json: {
        ok: true,
        post_uuid: req.post_uuid,
        post_id: req.post_id,
        media_type: mediaType,
        status: 'PUBLISHED',
        container_id: parentContainerId,
        child_container_ids: childIds,
        published_id: publishedId,
        published_url: permalink
      }
    }];
  } catch (err) {
    return await failConfirmedPrePublish('PUBLISH_FAILED', 'ORCHESTRATION', err && err.message ? err.message : 'Unexpected publish failure', true);
  }
}).call(this);
